<script setup>
import {ref,onMounted} from 'vue'
import {request} from './client'
const data=ref(null),busy=ref(false),error=ref(''),note=ref(''),reason=ref(''),expanded=ref(false)
async function load(){data.value=await request('plan_catalog','admin_get')}
async function run(fn){busy.value=true;error.value='';note.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function publish(){await run(async()=>{data.value=await request('plan_catalog','publish',{plans:data.value.plans,revision:data.value.revision,reason:reason.value});reason.value='';note.value='Plans published. Customer plan cards update when reloaded. Issued invoices are unchanged.'})}
onMounted(()=>run(load))
</script>
<template><section class="panel owner-block"><button class="button subtle" :aria-expanded="expanded" @click="expanded=!expanded">{{expanded?'Close plan editor':'Edit subscription plans'}}</button><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="note" role="status">{{note}}</p><form v-if="expanded && data" @submit.prevent="publish"><h2>Plan catalogue · revision {{data.revision}}</h2><p>Changes apply to this site. Prices apply to newly issued LKR provider invoices. Feature changes apply to current providers on their next request. Existing invoices, trial dates and paid periods stay unchanged.</p><p>Feature switches control access to existing tools. A feature still requires its service credentials. Student limits, device limits and per-student usage rates are not editable here.</p><div class="plan-editor-grid"><fieldset v-for="(plan,name) in data.plans" :key="name" :disabled="busy"><legend>{{name}}</legend><label>Monthly price · LKR<input type="number" v-model.number="plan.monthly_lkr" min="1" max="10000000" step="1" required></label><label>Description<textarea v-model="plan.description" maxlength="500" rows="3"></textarea></label><label v-for="key in data.editable_features" :key="key" class="plan-feature"><input type="checkbox" v-model="plan.features[key]">{{key.replaceAll('_',' ')}}</label></fieldset></div><label>Reason for change<textarea v-model="reason" minlength="10" maxlength="1000" required :disabled="busy"></textarea></label><div class="plan-editor-buttons"><button class="button primary" :disabled="busy">{{busy?'Saving…':'Publish plan changes'}}</button><button type="button" class="button subtle" :disabled="busy" @click="run(load)">Discard edits & reload</button></div></form></section></template>
<style scoped>.plan-editor-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:20px 0}.plan-editor-grid fieldset{min-width:0;border:1px solid #e5ddeb;border-radius:14px;padding:20px}.plan-editor-grid legend{font-weight:700;padding:0 8px}.plan-editor-grid label{margin-bottom:14px}.plan-editor-grid .plan-feature{flex-direction:row;align-items:center;gap:10px;text-transform:capitalize}.plan-feature input{width:18px;height:18px;accent-color:#53238a}.plan-editor-buttons{display:flex;flex-wrap:wrap;gap:12px;margin-top:18px}@media(max-width:700px){.plan-editor-grid{grid-template-columns:1fr}}</style>
